using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoastalTerrainVerify{static CoastalTerrainVerify(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalTerrainVerify.request")||EditorApplication.isCompiling)return;File.Delete("CoastalTerrainVerify.request");var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var terrain=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain").GetComponentInChildren<Terrain>();int sampled=0,intrusions=0;float worst=0;var read=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic);foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var renderer=f.GetComponent<MeshRenderer>();if(!renderer||!renderer.sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name.StartsWith("City PNG"))))continue;var data=read.Invoke(null,new object[]{f.sharedMesh});var points=(Vector3[])data.GetType().GetField("p").GetValue(data);foreach(var local in points){var p=f.transform.TransformPoint(local);var uv=new Vector2((p.x-terrain.transform.position.x)/terrain.terrainData.size.x,(p.z-terrain.transform.position.z)/terrain.terrainData.size.z);if(uv.x<0||uv.y<0||uv.x>=1||uv.y>=1)continue;if(terrain.terrainData.IsHole(Mathf.FloorToInt(uv.x*512),Mathf.FloorToInt(uv.y*512)))continue;sampled++;float delta=terrain.SampleHeight(p)-p.y;worst=Mathf.Max(worst,delta);if(delta>.2f)intrusions++;}}log.AppendLine("Terrain count: "+scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain").GetComponentsInChildren<Terrain>().Length);log.AppendLine("Road vertex samples intersecting terrain footprint: "+sampled+"; terrain above road by >0.2m: "+intrusions+"; maximum intrusion: "+worst);log.AppendLine("Shader errors: "+ShaderUtil.GetShaderMessages(terrain.materialTemplate.shader).Count(m=>m.severity.ToString()=="Error"));var shaders=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain").GetComponentsInChildren<MeshRenderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Distinct();log.AppendLine("Detail shader errors: "+shaders.Sum(s=>ShaderUtil.GetShaderMessages(s).Count(m=>m.severity.ToString()=="Error")));log.AppendLine("Instancing: "+terrain.drawInstanced+"; maximum LOD: "+terrain.heightmapMaximumLOD+"; pixel error: "+terrain.heightmapPixelError+"; terrain layers: "+terrain.terrainData.terrainLayers.Length+"; trees: "+terrain.terrainData.treeInstanceCount);}catch(Exception e){log.AppendLine(e.ToString());}File.WriteAllText("FinalEnvironmentRoadReview/CoastalTerrainValidation.txt",log.ToString());}}